mapper.select:
SELECT s.id AS spot_id, s.type AS type, s.name AS name, ST_Latitude(s.location) AS lat, ST_Longitude(s.location) AS lng, s.park_warning AS park_warning, d.operating_status AS operating_status, d.closed_from AS closed_from, d.closed_until AS closed_until, ST_Distance_Sphere(s.location, ST_SRID(POINT(#{nearby.centerLng}, #{nearby.centerLat}), 4326)) AS distance_meters FROM spot s LEFT JOIN public_spot_detail d ON d.spot_id = s.id LEFT JOIN bakji_detail b ON b.spot_id = s.id WHERE s.status = 'ACTIVE' AND MBRIntersects( ST_SRID( POLYGON(LINESTRING( POINT(#{nearby.swLng}, #{nearby.swLat}), POINT(#{nearby.neLng}, #{nearby.swLat}), POINT(#{nearby.neLng}, #{nearby.neLat}), POINT(#{nearby.swLng}, #{nearby.neLat}), POINT(#{nearby.swLng}, #{nearby.swLat}))), 4326), s.location) AND ST_Distance_Sphere(s.location, ST_SRID(POINT(#{nearby.centerLng}, #{nearby.centerLat}), 4326)) <= #{nearby.radiusMeters}
AND s.type IN
#{type}
AND (s.type <> 'BAKJI' OR b.has_water = TRUE)
AND (s.type <> 'BAKJI' OR b.has_toilet = TRUE)
AND s.park_warning = FALSE
ORDER BY distance_meters, s.id LIMIT #{limit} OFFSET #{offset}
